import{c as e,U as a,j as d,m as i}from"./chunks/framework.DQFmIr4R.js";const b=JSON.parse('{"title":"分卷","description":"","frontmatter":{},"headers":[],"relativePath":"zh/specification/volumes.md","filePath":"zh/specification/volumes.md","lastUpdated":1782214112000}'),o={name:"zh/specification/volumes.md"};function r(l,t,s,h,c,n){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="分卷" tabindex="-1">分卷 <a class="header-anchor" href="#分卷" aria-label="Permalink to “分卷”">​</a></h1><p>当打包时指定 <code>--volume-size</code>，数据体（混淆后的压缩流）会被分割为多个分卷。</p><h2 id="文件命名" tabindex="-1">文件命名 <a class="header-anchor" href="#文件命名" aria-label="Permalink to “文件命名”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>命名</th></tr></thead><tbody><tr><td>单卷</td><td><code>output.ttp</code></td></tr><tr><td>多卷</td><td><code>output.ttp.001</code>, <code>output.ttp.002</code>, …</td></tr></tbody></table><p>卷序号固定为 3 位十进制数字（<code>001</code>–<code>999</code>）。</p><h2 id="头部字段" tabindex="-1">头部字段 <a class="header-anchor" href="#头部字段" aria-label="Permalink to “头部字段”">​</a></h2><p>每卷拥有独立 26 字节头部，其中分卷相关字段：</p><table tabindex="0"><thead><tr><th>偏移</th><th>大小</th><th>说明</th></tr></thead><tbody><tr><td>10</td><td>2</td><td>当前卷序号（uint16 LE，从 1 开始）</td></tr><tr><td>12</td><td>2</td><td>总卷数（uint16 LE）</td></tr><tr><td>14</td><td>4</td><td>本卷数据长度（uint32 LE）</td></tr></tbody></table><h2 id="拼接规则" tabindex="-1">拼接规则 <a class="header-anchor" href="#拼接规则" aria-label="Permalink to “拼接规则”">​</a></h2><p>各卷的<strong>数据体</strong>（头部之后、魔数校验之前的字节）依次拼接，即为完整的混淆压缩流：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>完整混淆流 = 卷1数据 + 卷2数据 + … + 卷N数据</span></span></code></pre></div><p>拼接后统一执行：逆置换 → 解压 → 解析载荷。</p><h2 id="解包流程" tabindex="-1">解包流程 <a class="header-anchor" href="#解包流程" aria-label="Permalink to “解包流程”">​</a></h2><ol><li>读取第一个分卷头部，获取总卷数</li><li>按 <code>001</code> → <code>002</code> → … 顺序读取各卷数据体</li><li>若实际找到的分卷数少于预期总卷数，视为数据不完整（实现应发出警告）</li><li>拼接所有数据体，执行后续处理</li></ol>',14)])])}const u=e(o,[["render",r]]);export{b as __pageData,u as default};
